// Sortable / filterable ADR index.
//
// Enhances the table generated by docs/scripts/convert_adrs.py (the ADR
// "Overview" page). No dependencies. Degrades gracefully: with JS off, the
// table still renders with colored badges, just without sort/filter.
(function () {
  "use strict";

  function initAdrIndex() {
    var root = document.querySelector(".adr-index");
    if (!root) {
      return;
    }
    var table = root.querySelector(".adr-table");
    var tbody = table.querySelector("tbody");
    var rows = Array.prototype.slice.call(tbody.querySelectorAll("tr"));
    var search = root.querySelector(".adr-search");
    var countEl = root.querySelector(".adr-count");
    var headers = Array.prototype.slice.call(
      table.querySelectorAll("th.adr-sortable")
    );

    var filters = { type: "", status: "", q: "" };
    var sortKey = "num";
    var sortDir = 1; // 1 = ascending, -1 = descending

    function cellValue(row, key) {
      if (key === "num") {
        return parseInt(row.getAttribute("data-num"), 10) || 0;
      }
      return (row.getAttribute("data-" + key) || "").toLowerCase();
    }

    function apply() {
      var q = filters.q.trim().toLowerCase();
      var shown = 0;
      rows.forEach(function (row) {
        var ok =
          (!filters.type || row.getAttribute("data-type") === filters.type) &&
          (!filters.status ||
            row.getAttribute("data-status") === filters.status) &&
          (!q || (row.getAttribute("data-search") || "").indexOf(q) !== -1);
        row.hidden = !ok;
        if (ok) {
          shown += 1;
        }
      });
      if (countEl) {
        countEl.textContent = shown + " of " + rows.length + " ADRs";
      }
    }

    function sortBy(key) {
      if (sortKey === key) {
        sortDir = -sortDir;
      } else {
        sortKey = key;
        sortDir = 1;
      }
      rows
        .slice()
        .sort(function (a, b) {
          var va = cellValue(a, key);
          var vb = cellValue(b, key);
          if (va < vb) {
            return -sortDir;
          }
          if (va > vb) {
            return sortDir;
          }
          return cellValue(a, "num") - cellValue(b, "num");
        })
        .forEach(function (row) {
          tbody.appendChild(row);
        });
      headers.forEach(function (th) {
        if (th.getAttribute("data-key") === key) {
          th.setAttribute(
            "aria-sort",
            sortDir === 1 ? "ascending" : "descending"
          );
        } else {
          th.removeAttribute("aria-sort");
        }
      });
    }

    root.querySelectorAll(".adr-chip").forEach(function (chip) {
      chip.addEventListener("click", function () {
        var facet = chip.getAttribute("data-facet");
        filters[facet] = chip.getAttribute("data-value");
        root
          .querySelectorAll('.adr-chip[data-facet="' + facet + '"]')
          .forEach(function (c) {
            c.classList.toggle("is-active", c === chip);
          });
        apply();
      });
    });

    if (search) {
      search.addEventListener("input", function () {
        filters.q = search.value;
        apply();
      });
    }

    headers.forEach(function (th) {
      th.setAttribute("role", "button");
      th.tabIndex = 0;
      th.addEventListener("click", function () {
        sortBy(th.getAttribute("data-key"));
      });
      th.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          sortBy(th.getAttribute("data-key"));
        }
      });
    });

    apply();
  }

  // Material / Zensical "instant loading" (navigation.instant) swaps page
  // content over XHR without a full reload, so DOMContentLoaded fires only
  // once. Subscribe to the theme's document$ observable, which emits on every
  // navigation, so the table is re-wired when you land on the ADR page. Fall
  // back to plain DOM events when the observable isn't available.
  if (window.document$ && typeof window.document$.subscribe === "function") {
    window.document$.subscribe(initAdrIndex);
  } else if (document.readyState !== "loading") {
    initAdrIndex();
  } else {
    document.addEventListener("DOMContentLoaded", initAdrIndex);
  }
})();
